def write_page(path, title, desc, body, canonical_rel, og="/assets/og/default.png", crumbs=None, extra_ld=None, noindex=False):
    d = os.path.dirname(path)
    if d: os.makedirs(d, exist_ok=True)
    crumbs_html = ''
    ld_crumbs = ''
    if crumbs:
        items = [("/", "Главная")] + list(crumbs)
        parts = []
        for idx2, (href, label) in enumerate(items):
            last = (idx2 == len(items) - 1)
            lab = html.escape(str(label))
            if last:
                parts.append('<li class="inline-flex items-center"><span class="text-gray-900 font-medium" aria-current="page">' + lab + '</span></li>')
            else:
                parts.append('<li class="inline-flex items-center"><a class="text-gray-500 hover:text-green-600" href="' + href + '">' + lab + '</a>'
                    '<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="mx-2 text-gray-400"><path d="M9 6l6 6-6 6"/></svg></li>')
        crumbs_html = '<nav aria-label="Хлебные крошки"><ul class="flex flex-wrap items-center text-sm py-4">' + ''.join(parts) + '</ul></nav>'
        ld_list = []
        for idx2, (href, label) in enumerate(items):
            item = '{"@type":"ListItem","position":' + str(idx2 + 1) + ',"name":"' + html.escape(str(label)).replace('"','') + '"'
            if href:
                item += ',"item":"' + SITE_DOMAIN + href + '"'
            item += '}'
            ld_list.append(item)
        ld_crumbs = '<script type="application/ld+json">{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[' + ','.join(ld_list) + ']}</script>'
    doc = ('<!DOCTYPE html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
     '<meta name="color-scheme" content="light">'
     '<title>' + html.escape(title) + '</title>'
     '<meta name="description" content="' + html.escape(desc) + '">'
     '<link rel="icon" href="/favicon.ico" sizes="any"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="apple-touch-icon" href="/apple-touch-icon.png"><link rel="manifest" href="/site.webmanifest">'
     '<meta property="og:type" content="article"><meta property="og:image" content="' + SITE_DOMAIN + og + '">'
     '<meta property="og:title" content="' + html.escape(title) + '"><meta property="og:description" content="' + html.escape(desc[:200]) + '">'
     '<meta property="og:url" content="' + SITE_DOMAIN + canonical_rel + '"><meta property="og:site_name" content="' + SITE_NAME + '">'
     '<link rel="canonical" href="' + SITE_DOMAIN + canonical_rel + '">' + ('<meta name="robots" content="noindex, follow">' if noindex else '') + YANDEX_META + GSC_META +
     '<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>'
     '<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap">'
     '<link rel="stylesheet" href="/assets/fc-theme.css?v=' + BUILD_STAMP + '">'
     '<link rel="stylesheet" href="/style.css?v=' + BUILD_STAMP + '">'
     '<script type="application/ld+json">{"@context":"https://schema.org","@type":"WebPage","name":"' + html.escape(title) + '","description":"' + html.escape(desc[:250]) + '","inLanguage":"ru"}</script>' + ld_crumbs + (extra_ld or "") + METRIKA_JS +
     '</head><body>' + header_html(canonical_rel) + BANNER_HTML + '<main class="container my-4">' + crumbs_html + body + _comments_html(path) + '</main>' + FOOTER + SHARE_JS + NAV_JS + catalog.ORDER_JS + '</body></html>')
    with open(path,'w',encoding='utf-8') as f: f.write(_ext_fix(doc))

def src_html(p):
    links = [s for s in p['src'] if s.startswith('http')]
    if links:
        return 'Источники: ' + ' '.join('<a href="'+s+'">'+html.escape(re.sub(r"^https?://(www\\.)?","",s)[:70])+'</a>' for s in links)
    return 'Решение собрано по отзывам владельцев на профильных форумах и сервисах'

