def _fmt1(x):
    s = ('%.1f' % x).rstrip('0').rstrip('.').replace('.', ',')
    return s

def tl_short(pids, maxs=2):
    out = []
    for i in pids[:2]:
        s = PAINS[i]['sol'].split('. ')[0].strip()
        if len(s) > 160: s = s[:157].rstrip() + '…'
        out.append(s)
    return '. '.join(out) + '.'

