EX_CSS = EX_CSS + "\n/* --- главная в стиле GCC: инструменты, трендовые модели, бренды --- */\n.tools-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(246px,1fr));gap:12px;margin:14px 0 8px}\n.tool{background:#fff;border:1px solid var(--line);border-radius:16px;padding:16px;display:flex;gap:12px;align-items:flex-start;text-decoration:none;transition:box-shadow .15s ease}\n.tool:hover{box-shadow:0 4px 8px rgba(0,0,0,.06),0 12px 28px rgba(0,0,0,.10)}\n.tool svg{flex:none;width:40px;height:40px;border-radius:11px;background:var(--marine);padding:9px;box-sizing:border-box}\n.tool-body{display:flex;flex-direction:column;gap:4px}\n.tool b{display:block;color:var(--marine);font-size:15.5px;letter-spacing:-.01em}\n.tool-body>span{font-size:13.5px;color:#5f5f66;line-height:1.4}\n.tgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(268px,1fr));gap:14px;margin:14px 0 8px}\n.mcard2{background:#fff;border:1px solid var(--line);border-radius:16px;overflow:hidden;text-decoration:none;display:flex;flex-direction:column;transition:box-shadow .15s ease}\n.mcard2:hover{box-shadow:0 4px 8px rgba(0,0,0,.06),0 12px 28px rgba(0,0,0,.10)}\n.mcard2-media{aspect-ratio:16/9;overflow:hidden;background:#f5f5f7}\n.mcard2-media img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .25s ease}\n.mcard2:hover .mcard2-media img{transform:scale(1.03)}\n.mcard2-body{padding:12px 14px 14px;display:flex;flex-direction:column;gap:8px}\n.mcard2-body>b{color:var(--marine);font-size:16px;letter-spacing:-.015em}\n.mcard2-specs{display:flex;flex-wrap:wrap;gap:5px}\n.mcard2-specs span{font-size:12px;background:#f5f5f7;border-radius:6px;padding:3px 8px;color:#5f5f66}\n.mcard2-link{font-size:13.5px;color:var(--marine);font-weight:600;margin-top:auto}\n.brand-strip{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0 4px}\n.brand-strip a{font-size:13.5px;padding:8px 13px;border:1px solid var(--line);border-radius:12px;color:var(--marine);background:#fff;text-decoration:none;font-weight:500}\n.brand-strip a:hover{background:#f4faef}\n.brand-strip a span{color:#86868b;font-size:12px;margin-left:4px}\n@media (max-width:520px){.tools-grid{grid-template-columns:1fr 1fr}.tgrid{grid-template-columns:1fr}.tool svg{width:34px;height:34px;padding:7px}}\n"


def main():
    global CSS
    outdir = sys.argv[1] if len(sys.argv) > 1 else '_site'
    catalog.init(write_page, MODELS, SITE_DOMAIN)
    global BUILD_DATE
    BUILD_DATE = date.today().isoformat()
    global BUILD_STAMP
    BUILD_STAMP = BUILD_DATE + '-' + str(int(time.time()))
    repo_root = os.path.dirname(os.path.abspath(__file__))
    data_dir = os.path.join(repo_root, 'data')
    os.makedirs(outdir, exist_ok=True)
    os.makedirs(os.path.join(outdir,'assets'), exist_ok=True)
    LOGO = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="14" fill="#003a40"/><path d="M37 8 L16 38 h14 l-5 18 25-34 H34 l8-14 z" fill="#ffffff"/></svg>'
    with open(os.path.join(outdir,'assets','logo.svg'),'w',encoding='utf-8') as f: f.write(LOGO)
    CSS = CSS + EX_CSS + UTIL_CSS
    with open(os.path.join(outdir,'style.css'),'w',encoding='utf-8') as f: f.write(CSS)
    favicon_files(outdir)
    # leaflet
    lf = os.path.join(repo_root,'static','leaflet')
    if os.path.isdir(lf):
        dst = os.path.join(outdir,'assets','leaflet')
        if os.path.isdir(dst): shutil.rmtree(dst)
        shutil.copytree(lf, dst)
    # фото товаров каталога (assets/sku)
    # PDF-гид (лид-магнит)
    gdir = os.path.join(repo_root,'assets','guide')
    if os.path.isdir(gdir):
        gdst = os.path.join(outdir,'assets','guide')
        if os.path.isdir(gdst): shutil.rmtree(gdst)
        shutil.copytree(gdir, gdst)
    sku_dir = os.path.join(repo_root,'assets','sku')
    if os.path.isdir(sku_dir):
        dst = os.path.join(outdir,'assets','sku')
        if os.path.isdir(dst): shutil.rmtree(dst)
        shutil.copytree(sku_dir, dst)
    # FreshCart theme css
    fcc = os.path.join(repo_root,'assets','fc-theme.css')
    if os.path.isfile(fcc):
        fdst = os.path.join(outdir,'assets','fc-theme.css')
        os.makedirs(os.path.dirname(fdst), exist_ok=True)
        shutil.copy(fcc, fdst)
    # админка (неиндексируемая)
    adir = os.path.join(repo_root,'admin')
    if os.path.isdir(adir):
        adst = os.path.join(outdir,'admin')
        if os.path.isdir(adst): shutil.rmtree(adst)
        shutil.copytree(adir, adst)
        with open(os.path.join(outdir,'admin','robots.txt'),'w',encoding='utf-8') as f: f.write('User-agent: *\nDisallow: /admin/\n')
        ap = os.path.join(adst,'index.html')
        if os.path.isfile(ap):
            _h = open(ap,encoding='utf-8').read()
            if '<meta name="robots"' not in _h:
                _h = _h.replace('</head>', '<meta name="robots" content="noindex, nofollow"></head>', 1)
                open(ap,'w',encoding='utf-8').write(_h)
    news = load_news(data_dir)
    news_map = load_news_map(data_dir)
    print('Новостей в базе:', len(news))
    home_page(outdir, news)
    pains_index(outdir)
    slugs = [model_page(m, outdir) for m in MODELS]
    for sl,title,desc,pids in PAIN_ARTICLES:
        pain_article_page(sl,title,desc,pids,outdir)
    for it in news:
        news_page(it, outdir, news_map)
    news_index(news, outdir)
    news_feed(news, outdir)
    vin_slugs = []
    for brand in sorted(VIN_BRANDS):
        if brand in [m['brand'].strip() for m in MODELS] or True:
            vin_slugs.append(vin_brand_page(brand, outdir))
    vin_hub(outdir)
    map_page(outdir)
    # stations.json: готовый статический файл (обновляется отдельно из OSM)
    st_src = os.path.join(repo_root,'static','charging','stations.json')
    dst_json = os.path.join(outdir,'charging','stations.json')
    os.makedirs(os.path.dirname(dst_json), exist_ok=True)
    if os.path.isfile(st_src):
        shutil.copy(st_src, dst_json)
        print('stations.json:', len(json.load(open(st_src, encoding='utf-8')).get('stations', [])), 'станций')
    else:
        json.dump({'updated': BUILD_DATE, 'stations': []}, open(dst_json,'w',encoding='utf-8'), ensure_ascii=False)
        print('stations.json: пустой (нет static/charging/stations.json)')
    idx = []
    for m in MODELS:
        idx.append({'t': m['brand']+' '+m['model'], 'd': 'Разъёмы: '+str(m.get('ac') or '—')+' / '+str(m.get('dc') or '—')+' · '+m['type']+' · '+m['market'], 'u': '/models/'+slug(m['brand'])+'-'+slug(m['model'])+'.html'})
    for sl,title,desc,_ in PAIN_ARTICLES:
        idx.append({'t': title, 'd': desc, 'u': '/pain/'+sl+'.html'})
    for it in news:
        idx.append({'t': it['title'], 'd': it.get('teaser') or '', 'u': news_slug_page(it)})
    for brand in VIN_BRANDS:
        idx.append({'t': 'VIN '+brand, 'd': 'Расшифровка VIN, код года, проверка истории ('+VIN_BRANDS[brand][0]+')', 'u': '/vin/'+slug(brand)+'.html'})
    for t,u,d in [('/', 'Запас хода', 'Справочник по зарядке EV в России'), ('/charging/','Карта зарядных станций','ЗУ по данным OSM'), ('/pains.html','Проблемы и решения','12 руководств')]:
        idx.append({'t': t, 'd': d, 'u': u})
    search_page(outdir, idx)
    llms_files(outdir, news)
    about_page(outdir, news)
    misc_pages(outdir)
    # OG-карточки: новости + бренды VIN + дефолт
    jobs = [('/assets/og/default.png', 'Запас хода — практика владения электромобилем в России')]
    for it in news:
        jobs.append(('/assets/og/n-'+it['date']+'-'+it['slug']+'.png', it['title']))
    for brand in VIN_BRANDS:
        jobs.append(('/assets/og/vin-'+slug(brand)+'.png', 'VIN '+brand+': расшифровка и проверка истории'))
    for sl,title,_,_ in PAIN_ARTICLES:
        jobs.append(('/assets/og/p-'+sl+'.png', title))
    og_gen(outdir, jobs)
    # OG для моделей (145) — упрощённые (заголовок покороче)
    for m in MODELS:
        jobs.append(('/assets/og/m-'+slug(m['brand'])+'-'+slug(m['model'])+'.png', m['brand']+' '+m['model']+' — разъёмы зарядки'))
    og_gen(outdir, jobs)
    catalog.catalog_build(outdir)
    services.services_build(outdir, write_page)
    services.blog_build(outdir, write_page)
    services.b2b_build(outdir, write_page)
    services.brands_build(outdir, write_page, MODELS)
    services.open_data_build(outdir, write_page)
    models_index(outdir)
    forum_build(outdir)
    quiz_page(outdir)
    app_page(outdir)
    compare_page(outdir)
    with open(os.path.join(outdir,'sitemap.xml'),'w',encoding='utf-8') as f: f.write(build_sitemap(slugs, news, vin_slugs))
    total = sum(len(fs) for _,_,fs in os.walk(outdir))
    print('Готово: моделей', len(slugs), '| новостей', len(news), '| VIN-страниц', len(vin_slugs), '| файлов в _site:', total)

if __name__ == '__main__':
    main()